int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long k, w;
    if (!(cin >> k >> w)) return 0;

    // If k == 1, only one string of each length exists.
    // For w >= 2, the longest substring that is also a weak subsequence
    // is infinite in length (since any length is possible), so answer is -1.
    if (k == 1) {
        cout << -1 << '\n';
        return 0;
    }

    // For k >= 2, the answer is k^w modulo MOD.
    cout << modpow(k % MOD, w) << '\n';
    return 0;
}

