// Multiply 2x2 matrices
struct Mat {
    long long a00, a01, a10, a11;
};

Mat mul(const Mat &x, const Mat &y) {
    Mat r;
    r.a00 = (x.a00 * y.a00 + x.a01 * y.a10) % MOD;
    r.a01 = (x.a00 * y.a01 + x.a01 * y.a11) % MOD;
    r.a10 = (x.a10 * y.a00 + x.a11 * y.a10) % MOD;
    r.a11 = (x.a10 * y.a01 + x.a11 * y.a11) % MOD;
    return r;
}

Mat mpow(Mat base, long long e) {
    Mat r{1, 0, 0, 1};
    while (e > 0) {
        if (e & 1) r = mul(r, base);
        base = mul(base, base);
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long k, w;
    if (!(cin >> k >> w)) return 0;

    if (k == 1) {
        if (w == 2) {
            cout << 1 << '\n';
        } else {
            cout << -1 << '\n';
        }
        return 0;
    }

    // For k >= 2, number of strings is finite.
    // We use formula: sum_{n=1..w} k^n + sum_{n=w+1..2w-1} (k^n - k^{n-w})
    // This simplifies to: S = (k^{2w} - k^w)/(k-1) - (k^{w-1} - 1)/(k-1)
    // We compute via linear recurrence using matrix exponentiation.

    long long kw = modpow(k, w);
    long long kw1 = modpow(k, w - 1);

    // Compute k^{2w} via matrix exponentiation of recurrence:
    // f(n) = k*f(n-1), but we need big exponent; easier: k^{2w} = (k^w)^2 mod.
    long long k2w = (kw * kw) % MOD;

    long long inv = modpow(k - 1, MOD - 2);

    long long term1 = (k2w - kw) % MOD;
    if (term1 < 0) term1 += MOD;
    term1 = (term1 * inv) % MOD;

    long long term2 = (kw1 - 1) % MOD;
    if (term2 < 0) term2 += MOD;
    term2 = (term2 * inv) % MOD;

    long long ans = (term1 - term2) % MOD;
    if (ans < 0) ans += MOD;

    cout << ans << '\n';
    return 0;
}

