    long long cur = 1;
    long long powk = 1;
    long long prev = 0;

    for (long long i = 1; i <= w; ++i) {
        powk = powk * k % MOD;
        long long val = (powk - cur + MOD) % MOD;
        ans = (ans + val) % MOD;
        long long nxt = (cur * k + prev) % MOD;
        prev = cur;
